export interface TopicProblemItem extends CodingProblem {
  topicId: string;
  topicName: string;
  batch: number; // 1 = initial batch, 2 = unlocked after mastery
  hints: string[];
}

/**
 * Standard templates for problem generation
 */
function createProblem(
  topicId: string,
  topicName: string,
  num: number,
  title: string,
  difficulty: Difficulty,
  description: string,
  examples: { input: string; output: string; explanation?: string }[],
  functionName: string,
  testCases: TestCase[],
  starterJs: string,
  starterPy: string,
  batch = 1,
  hints = ['Consider boundary conditions first.', 'Think about optimal time vs space trade-offs.']
): TopicProblemItem {
  const xpReward = difficulty === 'easy' ? 10 : difficulty === 'medium' ? 20 : 40;
  return {
    id: `mq_${topicId}_${num}`,
    title,
    platform: 'leetcode',
    platformProblemNumber: String(100 + num),
    difficulty,
    xpReward,
    category: topicName,
    tags: [topicName, difficulty.toUpperCase()],
    description,
    constraints: [
      '1 <= n <= 10^5',
      'All values within standard 32-bit signed integer bounds',
      'Time complexity constraint: O(n log n) or better',
    ],
    examples,
    functionName,
    testCases,
    starterCode: {
      javascript: starterJs,
      python: starterPy,
      cpp: `// C++ Starter\n// Implement solution for ${title}\n`,
      java: `// Java Starter\n// Implement solution for ${title}\n`,
    },
    sourceUrl: `https://leetcode.com/problemset/all/?topicSlugs=${topicId}`,
    topicId,
    topicName,
    batch,
    hints,
  };
}

