// Combine all problems into a flat catalog with 16-20 per topic
export const ALL_INITIAL_CODING_CATALOG: TopicProblemItem[] = [
  ...INITIAL_TOPIC_PROBLEMS,
  ...OTHER_TOPICS.flatMap((topic) =>
    topic.problems.map((p, idx) =>
      createProblem(
        topic.id,
        topic.name,
        idx + 1,
        p.title,
        p.diff,
        p.desc,
        [{ input: JSON.stringify(p.inp[0]), output: JSON.stringify(p.out) }],
        p.fn,
        [
          {
            id: `tc_${topic.prefix}_${idx + 1}_1`,
            input: p.inp,
            inputFormatted: p.inp.map((x) => JSON.stringify(x)).join(', '),
            expectedOutput: p.out,
            expectedOutputFormatted: JSON.stringify(p.out),
          },
        ],
        p.codeJs,
        `# Python starter for ${p.title}\ndef ${p.fn}(*args):\n    pass\n`,
        idx >= 12 ? 2 : 1, // Unlockable higher batch
        [
          `Review the standard pattern for ${topic.name}.`,
          'Pay special attention to edge cases and off-by-one errors.',
        ]
      )
    )
  ),
];
